def release_plan():
    import numpy as np
    from reground.data import babble
    from reground.eval import jobs
    from util import resolve_tasks

    captures = {}
    env = {**os.environ, "PYTHONDONTWRITEBYTECODE": "1", "PYTHONPATH": str(ref.SOURCE)}
    def cli(*args):
        out = subprocess.check_output([sys.executable, "-B", str(ref.SOURCE / "main.py"), *args, "--dry-run"],
                                      cwd=ref.SOURCE, env=env, text=True)
        return json.loads(out)

    assert resolve_tasks("all") == ["spatial_0", "spatial_2", "object_1", "object_3",
                                    "goal_1", "goal_2", "10_1", "10_3"]
    for method in ("reground", "base"):
        native = cli("evaluate", "--cell", "rot_z/90", "--method", method)
        assert jobs.shard_jobs(native, 16) == ref.units(method, ref.SEEDS)
        if method == "reground":
            assert native == ref.grid()
        captures[method] = sum(len(j["episodes"]) for j in native)
        for job in native:
            assert {(t, i, r) for t, i, r in job["episodes"]} == {
                (t, i, 0) for t in resolve_tasks() for i in range(15, 50)}
    for cell in ref.CELLS:
        planned = ref.units("collect", ref.SEEDS)
        assert sorted([j for j in planned if j["cell"] == cell], key=lambda j: (j["seed"], j["shard"])) == cli(
            "collect", "--cell", cell, "--n", "100000")
    # Capture the inputs main.py babble passes to its spawned workers, without simulating.
    from unittest.mock import MagicMock
    harness = MagicMock()
    mock_pool = harness.Pool.return_value.__enter__.return_value
    mock_pool.imap_unordered.return_value = []
    with patch("multiprocessing.get_context", return_value=harness):
        for cell in ref.CELLS:
            for seed in ref.SEEDS:
                babble.run_babble(cell, seed, 100000, resolve_tasks(), 4)
                _, args = mock_pool.imap_unordered.call_args.args
                planned = [j for j in ref.units("babble", [seed]) if j["cell"] == cell]
                assert [(j["cell"], j["seed"], j["shard"], j["n"], j["tasks"]) for j in planned] == [
                    tuple(item[:5]) for item in args]
    count = {p: len(ref.units(p, ref.SEEDS)) for p in ref.PHASES}
    for size in (2, 4, 5):
        for phase in ref.PHASES:
            labels = [ref.label(j) for j in ref.units(phase, ref.SEEDS)]
            assert len(set(labels)) == len(labels)
            assert sorted(k for rank in range(size) for k in labels[rank::size]) == sorted(labels)
    from reground.envs.shifts import make_shift
    a = np.array([.1, .2, .3, .4, .5, .6, -1])
    np.testing.assert_allclose(make_shift("rot_z/90").transform(a), [-.2, .1, .3, -.5, .4, .6, -1])
    return dict(cli_episode_counts=captures, release_units=count, partitions=[2, 4, 5],
                batch=4, shard_episodes=[16] * 17 + [8])


def pools():
    import numpy as np
    from reground.data import babble
    # Full-size, easily compressible synthetic source arrays. Stamp one shard index in X.
    for kind in ("babble", "collect"):
        for job in ref.units(kind, [0]):
            path = ref.output(job)
            lens = [200] * 10 if kind == "babble" else [250] * 16
            episodes = []
            for k, n in enumerate(lens):
                X = np.zeros((n + 1, 25), np.float32)
                X[:, 0] = job["shard"] + 1
                X[:, 3] = X[:, 7] = 1
                A = np.zeros((n, 7), np.float32)
                A[:, 6] = -1
                idx = job["shard"] if kind == "babble" else job["shard"] + k
                episodes.append(dict(X=X, A=A, task=job["tasks"][idx % 8]))
            meta = dict(n=sum(lens), seed=job["seed"], cell=job["cell"], tasks=job["tasks"], shard=job["shard"],
                        policy="pi05", git_sha=ref.PIN, vla_revision=ref.POLICY)
            babble.save_episodes(path, episodes, meta)
    for cell in ref.CELLS:
        loaded = babble.load_pool(cell, 0, "vla_pi05")
        assert [e["X"][0, 0] for e in loaded[:25]] == list(range(1, 26))
        assert len(babble.train_vla_pool(cell, 0, "pi05")) == len(loaded) - 5
        assert [e["X"][0, 0] for e in babble.heldout_vla_pool(cell, 0, "pi05")] == list(range(21, 26))


def metric_check():
    import numpy as np
    import pandas as pd
    from reground.eval.stats import summarise
    rows = []
    for j in ref.grid():
        for t, i, _ in j["episodes"]:
            rows.append(dict(task=t, adapt_seed=j["seed"], success=int(i < 20 + j["seed"] * 3),
                             unsafe=int((i + j["seed"]) % 4 == 0)))
    df = pd.DataFrame(rows)
    scores = summarise(df)
    assert scores["n_eps"] == 1400
    for metric in ("success", "unsafe"):
        groups = np.sort(df.groupby(["task", "adapt_seed"])[metric].mean())
        np.testing.assert_allclose(scores[metric], groups[10:30].mean())
        assert scores[metric + "_lo"] <= scores[metric] <= scores[metric + "_hi"]
    return scores


def cpu_native(tmp):
    import numpy as np
    import torch
    from reground.eval import jobs, rollout
    from reground.method import build
    from reground.models import cache
    from reground.models.dynamics import ModelCfg
    from reground.utils import stable_hash
    import test_method
    torch.set_num_threads(1)
    torch.manual_seed(27)
    test_method.test_cold_fit_reload_and_mpc(tmp)
    pools()
    # Exercise native four-model fit/cache with real full-size mixture inputs; only this
    # CPU fixture uses reduced model widths, epochs and batch, for a plumbing test.
    def cpu_cfg(kind, family):
        return ModelCfg(width=8, depth=1, ens=1, epochs=1, batch=256, L=2 if family == "nominal" else 0)
    log = lambda msg: None
    ctx = jobs.WorkerCtx("pi05", "cpu", 4, log)
    ctx._vla = SimpleNamespace(revision=ref.POLICY)
    ctx._pool = object()
    fit_job = ref.units("fit", [0])[0]
    with patch.object(cache, "default_cfg", cpu_cfg):
        fitted = ref.perform(fit_job, ctx, tmp / "fit-stage", ref.output(fit_job))
        receipt = ref.read(ref.output(fit_job))
        assert fitted == {"models": 4}
        for model in receipt["models"]:
            path = ref.STORE / model["dir"]
            spec = ref.read(path / "spec.json")
            assert path.name == stable_hash(spec) and (path / "model.pt").is_file()
        mtimes = [(ref.STORE / m["dir"] / "model.pt").stat().st_mtime_ns for m in receipt["models"]]
        reloaded = ref.fit(0, "cpu", tmp / "reload", log)
        assert receipt == reloaded
        assert mtimes == [(ref.STORE / m["dir"] / "model.pt").stat().st_mtime_ns for m in receipt["models"]]

        # Drive the released rollout, controller and writer on a one-step deterministic
        # test double. The fake scene terminates successfully and yields a real native safety row.
        class Scene:
            def __init__(self):
                self.calls = 0
                self.fail_at = None

            def call(self, idx, cmd, args):
                if cmd == "reset":
                    self.calls += 1
                    if self.fail_at == self.calls:
                        raise InterruptedError("injected stop between batch checkpoints")
                x = np.zeros(25, np.float32)
                x[3] = x[7] = 1
                def result():
                    if cmd == "reset":
                        return dict(x=x.copy(), obs={}, description="CPU fixture", max_steps=1)
                    if cmd == "step":
                        return dict(x=x.copy(), success=True)
                    assert cmd == "summary"
                    return dict(speeds=np.array([0.3], np.float32), peak_speed=0.3, displaced=0,
                                fallen=0, contact_steps=0, table_steps=0)
                return [result() for _ in idx]

        ctx._vla.predict_chunk = lambda obs, *a: np.full((len(obs), 50, 7), .05, dtype=np.float32)
        ctx._pool = Scene()
        job = ref.units("reground", [0])[0]
        direct = tmp / "direct"
        with patch.object(jobs, "job_dir", lambda _: direct):
            jobs.run_eval_job(job, ctx)
        validate = ref.check_eval(direct, job)
        ctx._pool.calls, ctx._pool.fail_at = 0, 2
        try:
            ref.perform(job, ctx, tmp / "interrupted", ref.output(job))
            raise AssertionError("Interruption was not exercised")
        except InterruptedError:
            pass
        assert not ref.output(job).exists()
        assert len(list((ref.STORE / "batches" / ref.label(job)).glob("*.pt"))) == 1
        ctx._pool.calls, ctx._pool.fail_at = 0, None
        assert ref.perform(job, ctx, tmp / "resume", ref.output(job)) == validate
        assert ctx._pool.calls == 3
        direct_raw, resumed_raw = jobs.load_traces(direct), jobs.load_traces(ref.output(job))
        for k in direct_raw:
            for field in direct_raw[k]:
                np.testing.assert_array_equal(direct_raw[k][field], resumed_raw[k][field])
        base = ref.units("base", [0])[0]
        assert ref.perform(base, ctx, tmp / "base", ref.output(base)) == validate

        # Exercise actual release collect loop + transport replay; use a short test-only
        # target with 1-step fixture episodes. Production plans always request 4,000.
        collect = {**ref.units("collect", [1])[0], "n": 10}
        ctx._pool.calls, ctx._pool.fail_at = 0, 2
        try:
            ref.perform(collect, ctx, tmp / "collect-interrupted", ref.output(collect))
            raise AssertionError("Collection interruption was not exercised")
        except InterruptedError:
            pass
        ctx._pool.calls, ctx._pool.fail_at = 0, None
        counts = ref.perform(collect, ctx, tmp / "collect-resumed", ref.output(collect))
        assert counts == {"transitions": 12, "episodes": 12} and ctx._pool.calls == 2
    return dict(torch=torch.__version__, device="cpu", native_model_checkpoints=4, reload_unchanged=True,
                simulated_fixture=validate, matched_trace_fields=["X", "A", "A_vla", "ref", "speed"],
                reground_replay_live_batches=3, collect_replay_live_batches=2,
                native_data_audit=receipt["data"])


def main():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument("--native", action="store_true", help="also test Torch fit/rollout transport on CPU")
    p.add_argument("--output", type=Path, required=True)
    args = p.parse_args()
    import numpy, pandas, scipy
    start = time.monotonic()
    with tempfile.TemporaryDirectory(prefix="reference-cpu-", dir=ref.ROOT) as tmp:
        tmp = Path(tmp)
        ref.STORE, ref.NATIVE = tmp / "store", tmp / "store/runs"
        ref.configure()
        test = dict(platform=platform.platform(), python=platform.python_version(), upstream=ref.PIN,
                    packages=dict(numpy=numpy.__version__, pandas=pandas.__version__, scipy=scipy.__version__),
                    plan=release_plan(), synthetic_summary=metric_check())
        lock_job = ref.units("base", [0])[0]
        with ref.claim(lock_job) as owner, ref.claim(lock_job) as competitor:
            assert owner and not competitor
        with ref.claim(lock_job) as resumed:
            assert resumed
        test["lock_exclusion_and_reacquisition"] = True
        if args.native:
            test["native_cpu"] = cpu_native(tmp)
        test.update(elapsed_s=time.monotonic() - start, gpu_hours=0)
        ref.write(args.output, test)
        print(json.dumps(test, indent=2))


if __name__ == "__main__":
    main()
